<html><head><meta charset="utf-8"><style>body{font-family:Arial;color:#173b72}table{border-collapse:collapse;width:100%}th{background:#243dba;color:#fff;font-weight:bold}th,td{border:1px solid #b8c4d4;padding:8px}td.num{text-align:right}</style></head><body><h2>VAT Stock Report - {{ $firm->name }}</h2><p>Generated: {{ now()->format('Y-m-d H:i') }}</p><table><tr><th>Item</th><th>Unit</th><th>Available</th><th>Purchase Rate</th><th>Sale Rate</th><th>Reorder Level</th><th>Status</th></tr>@foreach($stocks as $stock)<tr><td>{{ $stock->item_name }}</td><td>{{ $stock->unit }}</td><td class="num">{{ number_format($stock->quantity,3) }}</td><td class="num">{{ number_format($stock->purchase_rate,2) }}</td><td class="num">{{ number_format($stock->sale_rate,2) }}</td><td class="num">{{ number_format($stock->reorder_level,3) }}</td><td>{{ $stock->quantity<=0?'Out of stock':($stock->reorder_level>0&&$stock->quantity<=$stock->reorder_level?'Low stock':'In stock') }}</td></tr>@endforeach</table></body></html>
